-- Master catalog restored from V1 (staging_catalogs for category + source image,
-- master_catalog for drive_file_id fallback/provenance).
-- Generated from v1_data_dump.json; 3,244 products.
begin;

create table if not exists app.master_catalog_products (
  id text primary key,
  name text not null,
  normalized_name text not null default '',
  category_label text not null default '',
  category_key text,
  price_minor bigint not null default 0 check (price_minor >= 0),
  image_url text not null default '',
  drive_file_id text not null default '',
  source_row integer,
  uploaded_at timestamptz,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table app.master_catalog_products is
  'Reference catalog copied from V1; supermarket merchants search it during product entry.';

create index if not exists master_catalog_products_active_name_idx
  on app.master_catalog_products (normalized_name) where active;

create index if not exists master_catalog_products_category_idx
  on app.master_catalog_products (category_key) where active;

alter table app.master_catalog_products enable row level security;

drop trigger if exists master_catalog_products_touch_updated_at
  on app.master_catalog_products;
create trigger master_catalog_products_touch_updated_at
  before update on app.master_catalog_products
  for each row execute function app.touch_updated_at();

on conflict (id) do update set name = excluded.name, normalized_name = excluded.normalized_name, category_label = excluded.category_label, category_key = excluded.category_key, price_minor = excluded.price_minor, image_url = excluded.image_url, drive_file_id = excluded.drive_file_id, source_row = excluded.source_row, uploaded_at = excluded.uploaded_at, updated_at = now(), active = true;

